import { Box, Container, Typography } from "@mui/material";
import React from "react";

const About = () => {
  return (
    <Box
      id="about"
      sx={{
        display: "flex",
        flexDirection: "column",
        minHeight: "70vh",
      }}
      points="0,100 50,00, 100,100"
    >
      <Container maxWidth="xl">
        <Typography
          sx={{ color: "primary.main", mx: 2, p: 2, textAlign: "center" }}
          variant="h4"
        >
          All-in-One Website Health Solution
        </Typography>

        <Typography sx={{ mx: 2, p: 2, textAlign: "center" }} variant="h6">
          10+ Years Of Experience in Medical Services
        </Typography>

        <Typography
          sx={{ mx: 2, p: 2, mb: 4, textAlign: "justify" }}
          variant="p"
        >
          With <strong>10+ years of experience</strong> in medical services, we take pride in delivering expert physiotherapy care that ensures faster recovery and long-term relief. Our <strong>patient-centered approach</strong> focuses on fair and accurate assessments, helping individuals regain mobility and live pain-free.
          <br />
          <br />
          Unlike typical online reviews that often reflect a negative bias, our methodology presents a <strong>true picture of patient satisfaction</strong>, showing that most individuals experience significant improvement. Negative bias in healthcare reviews can impact patient confidence, but we believe in fostering a <strong>positive care experience</strong> for everyone.
          <br />
          <br />
          Be sure to leave a review on <strong>Health Care</strong> for any physiotherapy treatment you’ve received—whether your experience was positive or had room for improvement. Your feedback helps others make informed decisions about their recovery.
          <br />
          <br />
          Connect with us on LinkedIn{" "}
          <a
            href="https://www.linkedin.com/in/PhysioPath72/"
            target="_blank"
            rel="noopener noreferrer"
          >
            <strong>@PhysioPath</strong>
          </a>{" "}
          and share your thoughts!
          <br />
          <br />
        </Typography>

      </Container>
    </Box>
  );
};

export default About;
